<?php
namespace App\Jobs;use App\Models\FaceSearchSubject;use App\Services\Face\FaceRecognitionManager;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Illuminate\Queue\Middleware\WithoutOverlapping;use Throwable;
class SearchFaces implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int$tries=3;public int$timeout=180;public function __construct(public int$subjectId){$this->onQueue('media-high');}public function backoff():array{return[10,45,180];}public function middleware():array{return[(new WithoutOverlapping('face-search-'.$this->subjectId))->expireAfter(240)->dontRelease()];}public function handle(FaceRecognitionManager$m):void{$s=FaceSearchSubject::findOrFail($this->subjectId);if(in_array($s->state,['completed','cancelled'],true))return;$s->update(['state'=>'processing']);try{$m->search($s);}catch(Throwable$e){$s->update(['state'=>'failed','error'=>'Face search failed.']);throw$e;}}}
